"""Exhaustive public-API surface + behavior audit of /workspace/six.py.

Every assertion is wrapped so that one failure does not hide the rest.
Prints PASS/FAIL per named check plus full tracebacks for failures.
"""
import sys, os, io, abc, types, operator, traceback, unittest, warnings, itertools

sys.path.insert(0, "/workspace")
import six

RESULTS = []


def check(name):
    def deco(fn):
        try:
            fn()
        except BaseException:
            RESULTS.append((name, "FAIL", traceback.format_exc()))
        else:
            RESULTS.append((name, "PASS", ""))
        return fn
    return deco


print("six loaded from:", six.__file__)

# ---------------------------------------------------------------- constants
@check("constants: existence of all required names")
def _():
    required = ["PY2", "PY3", "PY34", "string_types", "integer_types",
                "class_types", "text_type", "binary_type", "MAXSIZE",
                "__version__", "__author__"]
    missing = [n for n in required if not hasattr(six, n)]
    assert not missing, "missing attributes: %r" % (missing,)


@check("constants: values correct for py3.12")
def _():
    assert six.PY2 is False, six.PY2
    assert six.PY3 is True, six.PY3
    assert six.PY34 is True, six.PY34
    assert six.string_types == (str,), six.string_types
    assert six.integer_types == (int,), six.integer_types
    assert six.class_types == (type,), six.class_types
    assert six.text_type is str, six.text_type
    assert six.binary_type is bytes, six.binary_type
    assert six.__version__ == "1.17.0", six.__version__
    assert six.__author__ == "Benjamin Peterson", six.__author__


@check("constants: MAXSIZE is real max size (len of virtual seq raises)")
def _():
    assert six.MAXSIZE == sys.maxsize, (six.MAXSIZE, sys.maxsize)
    try:
        [] * six.MAXSIZE
    except OverflowError:
        raise AssertionError("MAXSIZE too large for multiplication")
    class X:
        def __len__(self):
            return six.MAXSIZE
    assert len(X()) == six.MAXSIZE
    class Y:
        def __len__(self):
            return six.MAXSIZE + 1
    try:
        len(Y())
    except OverflowError:
        pass
    else:
        raise AssertionError("MAXSIZE+1 did not overflow -> MAXSIZE wrong")


# ---------------------------------------------------------------- iterators
@check("iterators: next / advance_iterator / Iterator exist and work")
def _():
    assert six.next is six.advance_iterator, (six.next, six.advance_iterator)
    it = iter([1, 2])
    assert six.next(it) == 1
    assert six.advance_iterator(it) == 2
    try:
        six.next(it)
    except StopIteration:
        pass
    else:
        raise AssertionError("no StopIteration")
    assert six.Iterator is object, six.Iterator  # py3: Iterator is object

    class MyIt(six.Iterator):
        def __init__(self):
            self.n = 0
        def __next__(self):
            self.n += 1
            if self.n > 2:
                raise StopIteration
            return self.n
        def __iter__(self):
            return self
    assert list(MyIt()) == [1, 2]


D = {"a": 1, "b": 2}


@check("dicts: iterkeys/itervalues/iteritems return iterators not lists")
def _():
    for fname in ("iterkeys", "itervalues", "iteritems"):
        f = getattr(six, fname)
        r = f(D)
        assert not isinstance(r, list), "%s returned a list: %r" % (fname, r)
        assert iter(r) is r, "%s did not return an iterator: %r" % (fname, r)
        assert hasattr(r, "__next__"), fname
    assert sorted(six.iterkeys(D)) == ["a", "b"]
    assert sorted(six.itervalues(D)) == [1, 2]
    assert sorted(six.iteritems(D)) == [("a", 1), ("b", 2)]


@check("dicts: iterkeys/itervalues/iteritems forward **kwargs")
def _():
    sentinel = object()
    seen = {}

    class Recorder(dict):
        def keys(self, **kw):
            seen["keys"] = kw
            return iter(["k"])
        def values(self, **kw):
            seen["values"] = kw
            return iter(["v"])
        def items(self, **kw):
            seen["items"] = kw
            return iter([("k", "v")])

    r = Recorder()
    assert list(six.iterkeys(r, x=sentinel)) == ["k"]
    assert seen["keys"] == {"x": sentinel}, seen
    assert list(six.itervalues(r, y=sentinel)) == ["v"]
    assert seen["values"] == {"y": sentinel}, seen
    assert list(six.iteritems(r, z=sentinel)) == [("k", "v")]
    assert seen["items"] == {"z": sentinel}, seen


@check("dicts: iterlists works on object with .lists()")
def _():
    assert hasattr(six, "iterlists")
    seen = {}

    class WithLists(object):
        def lists(self, **kw):
            seen["kw"] = kw
            return iter([("a", [1, 2]), ("b", [3])])

    w = WithLists()
    r = six.iterlists(w)
    assert iter(r) is r, "iterlists did not return an iterator: %r" % (r,)
    assert list(r) == [("a", [1, 2]), ("b", [3])]
    assert list(six.iterlists(w, flat=True)) == [("a", [1, 2]), ("b", [3])]
    assert seen["kw"] == {"flat": True}, seen


@check("dicts: viewkeys/viewvalues/viewitems return real view objects")
def _():
    import collections.abc as cabc
    vk, vv, vi = six.viewkeys(D), six.viewvalues(D), six.viewitems(D)
    assert type(vk) is type({}.keys()), type(vk)
    assert type(vv) is type({}.values()), type(vv)
    assert type(vi) is type({}.items()), type(vi)
    assert isinstance(vk, cabc.KeysView), type(vk)
    assert isinstance(vv, cabc.ValuesView), type(vv)
    assert isinstance(vi, cabc.ItemsView), type(vi)
    # views are live and support set ops
    d = dict(D)
    v = six.viewkeys(d)
    d["c"] = 3
    assert "c" in v, "view not live"
    assert (six.viewkeys(D) & {"a"}) == {"a"}
    assert (six.viewitems(D) & {("a", 1)}) == {("a", 1)}
    assert len(vi) == 2


# ---------------------------------------------------------------- bytes/str
@check("bytes/str: b() round-trips \\x03 and friends")
def _():
    assert six.b("\x03") == b"\x03", six.b("\x03")
    assert six.b("\x03")[0] == 3
    assert six.b("\x00\xff") == b"\x00\xff"
    assert six.b("hi") == b"hi"
    assert isinstance(six.b("x"), six.binary_type)
    assert len(six.b("\x03")) == 1


@check("bytes/str: u() returns text")
def _():
    assert six.u("hi") == "hi"
    assert isinstance(six.u("hi"), six.text_type)
    assert six.u("ሴ") == "ሴ"


@check("bytes/str: unichr / int2byte / byte2int")
def _():
    assert six.unichr(65) == "A"
    assert six.unichr(0x1234) == "ሴ"
    assert six.int2byte(3) == b"\x03"
    assert isinstance(six.int2byte(3), bytes)
    assert six.byte2int(b"\x03") == 3
    assert six.byte2int(b"\x03abc") == 3
    try:
        six.byte2int(b"")
    except IndexError:
        pass
    else:
        raise AssertionError("byte2int(b'') did not raise IndexError")


@check("bytes/str: indexbytes / iterbytes")
def _():
    assert six.indexbytes(b"hello", 0) == ord("h")
    assert six.indexbytes(b"hello", 4) == ord("o")
    assert six.indexbytes(b"\x03\xff", 1) == 255
    assert list(six.iterbytes(b"abc")) == [97, 98, 99]
    assert list(six.iterbytes(b"")) == []
    it = six.iterbytes(b"ab")
    assert six.next(it) == 97


@check("bytes/str: StringIO / BytesIO")
def _():
    assert six.StringIO is io.StringIO
    assert six.BytesIO is io.BytesIO
    s = six.StringIO()
    s.write("ሴ")
    assert s.getvalue() == "ሴ"
    bo = six.BytesIO()
    bo.write(b"\x03")
    assert bo.getvalue() == b"\x03"


@check("ensure_binary: str and bytes input")
def _():
    assert six.ensure_binary("abc") == b"abc"
    assert six.ensure_binary(b"abc") == b"abc"
    assert isinstance(six.ensure_binary("abc"), bytes)
    assert six.ensure_binary("é") == "é".encode("utf-8")


@check("ensure_str: str and bytes input")
def _():
    assert six.ensure_str("abc") == "abc"
    assert six.ensure_str(b"abc") == "abc"
    assert isinstance(six.ensure_str(b"abc"), str)
    assert six.ensure_str("é".encode("utf-8")) == "é"


@check("ensure_text: str and bytes input")
def _():
    assert six.ensure_text("abc") == "abc"
    assert six.ensure_text(b"abc") == "abc"
    assert isinstance(six.ensure_text(b"abc"), str)
    assert six.ensure_text("é".encode("utf-8")) == "é"


@check("ensure_*: TypeError on non-str/bytes (int)")
def _():
    for fname in ("ensure_binary", "ensure_str", "ensure_text"):
        f = getattr(six, fname)
        for bad in (8, None, 3.5, [], object()):
            try:
                r = f(bad)
            except TypeError:
                pass
            except Exception as e:
                raise AssertionError("%s(%r) raised %s not TypeError: %s"
                                     % (fname, bad, type(e).__name__, e))
            else:
                raise AssertionError("%s(%r) did not raise TypeError, got %r"
                                     % (fname, bad, r))


@check("ensure_*: honour encoding= and errors= kwargs")
def _():
    # latin-1 encoding
    assert six.ensure_binary("é", encoding="latin-1") == b"\xe9"
    assert six.ensure_text(b"\xe9", encoding="latin-1") == "é"
    assert six.ensure_str(b"\xe9", encoding="latin-1") == "é"
    # positional form too (upstream signature: (s, encoding='utf-8', errors='strict'))
    assert six.ensure_binary("é", "latin-1") == b"\xe9"
    assert six.ensure_text(b"\xe9", "latin-1") == "é"
    # errors=
    assert six.ensure_text(b"\xff", encoding="utf-8", errors="ignore") == ""
    assert six.ensure_text(b"\xff", encoding="utf-8", errors="replace") == "�"
    assert six.ensure_str(b"\xff", errors="ignore") == ""
    assert six.ensure_binary("\ud800", encoding="utf-8", errors="ignore") == b""
    # errors=strict really raises
    try:
        six.ensure_text(b"\xff", encoding="utf-8", errors="strict")
    except UnicodeDecodeError:
        pass
    else:
        raise AssertionError("errors='strict' did not raise")
    # non-matching-type args are passed through unchanged (upstream semantics)
    assert six.ensure_binary(b"\xe9", encoding="latin-1") == b"\xe9"
    assert six.ensure_text("é", encoding="latin-1") == "é"


# ------------------------------------------------------- function/method attrs
class C(object):
    def m(self):
        return "m"


def gfunc(a, b=2, *args, **kw):
    x = a
    def inner():
        return x
    return inner


@check("func attrs: get_unbound_function")
def _():
    assert six.get_unbound_function(C.m) is C.m


@check("func attrs: create_bound_method")
def _():
    c = C()
    bm = six.create_bound_method(C.m, c)
    assert isinstance(bm, types.MethodType), type(bm)
    assert bm() == "m"
    assert six.get_method_self(bm) is c
    assert six.get_method_function(bm) is C.m


@check("func attrs: create_unbound_method")
def _():
    c = C()
    um = six.create_unbound_method(C.m, C)
    assert um is C.m
    assert um(c) == "m"


@check("func attrs: get_method_function / get_method_self")
def _():
    c = C()
    assert six.get_method_function(c.m) is C.m
    assert six.get_method_self(c.m) is c
    try:
        six.get_method_function(gfunc)
    except AttributeError:
        pass
    else:
        raise AssertionError("get_method_function on plain function should fail")


@check("func attrs: get_function_closure/code/defaults/globals")
def _():
    f = gfunc(1)
    assert six.get_function_closure(f) == f.__closure__
    assert six.get_function_closure(f) is not None
    assert six.get_function_code(gfunc) is gfunc.__code__
    assert six.get_function_defaults(gfunc) == (2,)
    assert six.get_function_globals(gfunc) is gfunc.__globals__


@check("func attrs: func_* aliases (py2-only names must be ABSENT on py3)")
def _():
    # Upstream six defines func_closure/func_code/func_defaults/func_globals
    # only under PY2.  On PY3 they must not exist.
    present = [n for n in ("func_closure", "func_code", "func_defaults",
                           "func_globals") if hasattr(six, n)]
    assert not present, "py2-only names leaked onto py3: %r" % (present,)


# ---------------------------------------------------------------- syntax
@check("syntax: exec_ with globals/locals")
def _():
    g = {}
    six.exec_("x = 42", g)
    assert g["x"] == 42
    g = {"y": 1}
    l = {}
    six.exec_("z = y + 1", g, l)
    assert l["z"] == 2, l
    # no-args form execs in caller frame
    six.exec_("""qq = 7""")
    assert locals().get("qq") == 7 or True  # frame semantics vary; just no crash


@check("syntax: exec_ 2- and 3-arg, and defaults to caller frame")
def _():
    def f():
        six.exec_("""in_frame = 99""")
        return locals()["in_frame"]
    assert f() == 99


@check("syntax: raise_from sets __cause__")
def _():
    cause = ValueError("the cause")
    try:
        six.raise_from(TypeError("outer"), cause)
    except TypeError as e:
        assert e.__cause__ is cause, e.__cause__
        assert str(e) == "outer"
    else:
        raise AssertionError("raise_from did not raise")
    # None cause
    try:
        six.raise_from(TypeError("t"), None)
    except TypeError as e:
        assert e.__cause__ is None, e.__cause__
    # class (not instance) as value
    try:
        six.raise_from(TypeError, cause)
    except TypeError as e:
        assert e.__cause__ is cause


@check("syntax: reraise preserves traceback")
def _():
    def deepest():
        raise ValueError("boom")

    try:
        deepest()
    except ValueError:
        tp, val, tb = sys.exc_info()
    orig_depth = len(traceback.extract_tb(tb))
    assert orig_depth >= 2, orig_depth
    try:
        six.reraise(tp, val, tb)
    except ValueError as e:
        new_tb = e.__traceback__
        frames = [f.name for f in traceback.extract_tb(new_tb)]
        assert "deepest" in frames, frames
        assert e is val
    else:
        raise AssertionError("reraise did not raise")


@check("syntax: reraise with value=None instantiates, and tb=None form")
def _():
    try:
        six.reraise(ValueError, None, None)
    except ValueError as e:
        assert type(e) is ValueError
    try:
        six.reraise(ValueError, ValueError("x"))
    except ValueError as e:
        assert str(e) == "x"


@check("syntax: reraise cleans up local variable tb")
def _():
    src = open(six.__file__).read()
    import re
    m = re.search(r"def reraise\(.*?\n(?=\n{2}|\Z)", src, re.S)
    assert m, "could not locate reraise source"
    body = m.group(0)
    assert "finally" in body, "reraise has no finally block:\n" + body
    assert "value = None" in body and "tb = None" in body, \
        "reraise does not clear locals:\n" + body
    # functional check: no reference cycle keeping the tb alive
    import gc, weakref
    class E(Exception):
        pass
    holder = []
    def make():
        try:
            raise E("x")
        except E:
            return sys.exc_info()
    tp, val, tb = make()
    ref = weakref.ref(val)
    try:
        six.reraise(tp, val, tb)
    except E:
        pass
    del tp, val, tb
    gc.collect()
    # the exception may legitimately still be alive via sys.exc_info in some
    # interpreters; only assert we can collect without error
    gc.collect()


@check("syntax: print_ basic + file= kwarg")
def _():
    out = six.StringIO()
    six.print_("hello", file=out)
    assert out.getvalue() == "hello\n", repr(out.getvalue())


@check("syntax: print_ sep= end= kwargs")
def _():
    out = six.StringIO()
    six.print_("a", "b", "c", sep="-", end="!", file=out)
    assert out.getvalue() == "a-b-c!", repr(out.getvalue())
    out = six.StringIO()
    six.print_(file=out)
    assert out.getvalue() == "\n", repr(out.getvalue())
    out = six.StringIO()
    six.print_("x", end="", file=out)
    assert out.getvalue() == "x", repr(out.getvalue())
    # sep/end None means default
    out = six.StringIO()
    six.print_("a", "b", sep=None, end=None, file=out)
    assert out.getvalue() == "a b\n", repr(out.getvalue())
    # bad types
    for kw in ("sep", "end"):
        try:
            six.print_("a", file=six.StringIO(), **{kw: 42})
        except TypeError:
            pass
        else:
            raise AssertionError("%s=42 did not raise TypeError" % kw)
    # unexpected kwarg
    try:
        six.print_("a", file=six.StringIO(), bogus=1)
    except TypeError:
        pass
    else:
        raise AssertionError("bogus kwarg accepted")


@check("syntax: print_ flush= kwarg actually flushes")
def _():
    flushed = []

    class F(io.StringIO):
        def flush(self):
            flushed.append(True)
            return io.StringIO.flush(self)

    f = F()
    six.print_("x", file=f)
    assert flushed == [], "flushed without flush=True: %r" % flushed
    six.print_("y", file=f, flush=True)
    assert flushed == [True], "flush=True did not flush: %r" % flushed


@check("syntax: print_ writes unicode and non-str objects")
def _():
    out = six.StringIO()
    six.print_("ሴ", file=out)
    assert out.getvalue() == "ሴ\n", repr(out.getvalue())
    out = six.StringIO()
    six.print_(42, None, [1, 2], {"k": 1}, file=out)
    assert out.getvalue() == "42 None [1, 2] {'k': 1}\n", repr(out.getvalue())
    out = six.StringIO()
    class R:
        def __str__(self):
            return "STR"
    six.print_(R(), file=out)
    assert out.getvalue() == "STR\n", repr(out.getvalue())
    # file=None -> no-op-ish (upstream returns early)
    six.print_("nothing", file=None)


@check("syntax: print_ defaults to sys.stdout looked up at CALL time")
def _():
    real = sys.stdout
    try:
        first = six.StringIO()
        sys.stdout = first
        six.print_("one")
        second = six.StringIO()
        sys.stdout = second
        six.print_("two")
    finally:
        sys.stdout = real
    assert first.getvalue() == "one\n", repr(first.getvalue())
    assert second.getvalue() == "two\n", repr(second.getvalue())


@check("syntax: wraps copies metadata and sets __wrapped__")
def _():
    def orig(a, b):
        """docstring here"""
        return a + b
    orig.custom = "attr"

    @six.wraps(orig)
    def wrapper(*a, **k):
        return orig(*a, **k)

    assert wrapper.__name__ == "orig", wrapper.__name__
    assert wrapper.__doc__ == "docstring here", wrapper.__doc__
    assert wrapper.__wrapped__ is orig
    assert wrapper.custom == "attr"
    assert wrapper(1, 2) == 3
    # wraps on a callable lacking __name__ must not explode (six's raison d'etre)
    class Callable(object):
        def __call__(self):
            return 1
    c = Callable()
    @six.wraps(c)
    def w2():
        return 2
    assert w2() == 2


# ------------------------------------------------------- classes / decorators
@check("with_metaclass: type of class is the metaclass")
def _():
    class Meta(type):
        pass

    class Base(object):
        pass

    class X(six.with_metaclass(Meta, Base)):
        pass

    assert type(X) is Meta, type(X)
    assert Base in X.__bases__, X.__bases__
    assert issubclass(X, Base)


@check("with_metaclass: no temporary base left in MRO/bases")
def _():
    class Meta(type):
        pass

    class Base(object):
        pass

    class X(six.with_metaclass(Meta, Base)):
        pass

    assert X.__bases__ == (Base,), X.__bases__
    assert X.__mro__ == (X, Base, object), X.__mro__
    names = [c.__name__ for c in X.__mro__]
    assert "temporary_class" not in names, names
    # default base is object
    class Y(six.with_metaclass(Meta)):
        pass
    assert Y.__bases__ == (object,), Y.__bases__
    assert Y.__mro__ == (Y, object), Y.__mro__


@check("with_metaclass: works with abc.ABCMeta (abstract enforcement)")
def _():
    class Base(six.with_metaclass(abc.ABCMeta, object)):
        @abc.abstractmethod
        def f(self):
            pass

    assert type(Base) is abc.ABCMeta, type(Base)
    try:
        Base()
    except TypeError as e:
        assert "abstract" in str(e), str(e)
    else:
        raise AssertionError("abstract class was instantiable")

    class Sub(Base):
        def f(self):
            return 1
    assert Sub().f() == 1


@check("with_metaclass: passes **kwargs through to metaclass")
def _():
    got = {}

    class Meta(type):
        def __new__(mcls, name, bases, d, **kwargs):
            got.update(kwargs)
            return super(Meta, mcls).__new__(mcls, name, bases, d)
        def __init__(cls, name, bases, d, **kwargs):
            super(Meta, cls).__init__(name, bases, d)

    class X(six.with_metaclass(Meta, kwarg=42)):
        pass

    assert got == {"kwarg": 42}, got
    assert type(X) is Meta


@check("with_metaclass: __prepare__ is honoured / not called on temp class")
def _():
    prepared = []

    class Meta(type):
        @classmethod
        def __prepare__(mcls, name, bases, **kw):
            prepared.append((name, bases, kw))
            return {}

    class X(six.with_metaclass(Meta, kw=1)):
        pass

    assert type(X) is Meta
    # the real class must be among the prepared names, with no temp class name
    names = [p[0] for p in prepared]
    assert "X" in names, prepared
    assert "temporary_class" not in names, prepared


@check("add_metaclass: sets metaclass, copies __dict__ minus __dict__/__weakref__")
def _():
    class Meta(type):
        pass

    @six.add_metaclass(Meta)
    class X(object):
        attr = "value"
        def meth(self):
            return 1

    assert type(X) is Meta, type(X)
    assert X.attr == "value"
    assert X().meth() == 1
    assert X.__name__ == "X"
    # instances must be weak-referenceable / have __dict__ (i.e. the descriptors
    # for the *new* class were used, the old ones were dropped)
    import weakref
    x = X()
    weakref.ref(x)
    x.foo = 1
    assert x.__dict__["foo"] == 1


@check("add_metaclass: removes slot descriptors when __slots__ present")
def _():
    class Meta(type):
        pass

    @six.add_metaclass(Meta)
    class X(object):
        __slots__ = ("a", "b")

    assert type(X) is Meta
    assert X.__slots__ == ("a", "b")
    x = X()
    x.a = 1
    x.b = 2
    assert (x.a, x.b) == (1, 2)
    try:
        x.c = 3
    except AttributeError:
        pass
    else:
        raise AssertionError("__slots__ not enforced after add_metaclass")
    assert not hasattr(x, "__dict__"), "slots class gained a __dict__"
    # str __slots__ form
    @six.add_metaclass(Meta)
    class Y(object):
        __slots__ = "only"
    y = Y()
    y.only = 5
    assert y.only == 5
    try:
        y.other = 1
    except AttributeError:
        pass
    else:
        raise AssertionError("str __slots__ not enforced")


@check("add_metaclass: preserves abstract methods (__abstractmethods__)")
def _():
    @six.add_metaclass(abc.ABCMeta)
    class X(object):
        @abc.abstractmethod
        def f(self):
            pass

    assert type(X) is abc.ABCMeta
    assert X.__abstractmethods__ == frozenset({"f"}), X.__abstractmethods__
    try:
        X()
    except TypeError as e:
        assert "abstract" in str(e), str(e)
    else:
        raise AssertionError("abstract class instantiable after add_metaclass")


@check("add_metaclass: does not copy __dict__/__weakref__ descriptors")
def _():
    class Meta(type):
        pass

